//! The `bsc work` subcommand — see the crate doc for why this noun exists.

use crate::gate::{classify, tally, GateResult, Verdict};
use bsc_cli_util::CmdDoc;
use std::path::{Path, PathBuf};

const TAGLINE: &str = "the work loop: run the gate and RECORD what it actually did on the change record";

/// The crate's own verb catalog. `pub` so `bsc surface verbs` can PROJECT it rather than
/// restate it — a generated catalog cannot drift, a second list does.
pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "gate",
        summary: "run the gate and record every leg's real result on this branch's change record",
        usage: "\
USAGE:
  bsc work gate [--full] [--ref <plan-ref>] [--strict] [--dry-run] [--json|--pretty]

Runs the real gate (`npm run gate`), streams its output untouched, then records EACH LEG on the change
record for this branch — from the machine-readable verdict the gate writes, never by scraping its log.

WHY THIS EXISTS. The change record is meant to be EVIDENCE that the gate ran, not a claim that it did.
Recording it by hand made it a claim: measured over five slices in one session, ~25 gate results were
read off a terminal and retyped. Nothing checked them, so a session could record `pass` for a leg that
failed or for one it never ran, and no surface would disagree. That is the same shape as a wake that
kills a pane and reports success — wrong in the safe-looking direction, with no durable trace.

THE REF IS THE BRANCH. This repo is 1:1 — one plan item, one ref, one branch, one worktree — so the
current branch names the change record. `--ref` overrides it; nothing is guessed when the branch is
not a ref, because recording a gate against the wrong item is worse than recording nothing.

A RED LEG IS ALWAYS RECORDED `fail`. A known-red declaration explains a failure; it never launders one
into a pass. What a declaration changes is the EXIT CODE, which follows UNEXPLAINED failures — a
statement about this run rather than a durable record of it. The summary always states the split
(`N red, M known-red -> K unexplained`) so that is never left implicit.

  --full     the unscoped gate — what step 7 runs before anything lands
  --strict   exit non-zero on ANY red, declared or not
  --dry-run  run the gate and print the verdict, recording nothing",
    },
    CmdDoc {
        name: "known-red",
        summary: "gate legs that are red for a reason no branch causes — each naming the item that owns it",
        usage: "\
USAGE:
  bsc work known-red list
  bsc work known-red add <leg-key> --ref <plan-ref> [--note <text>]
  bsc work known-red remove <leg-key>

`develop` can be red at a leg for a reason no branch causes — measured here for days at the repo-store
drift leg, owned by `develop-is-red-the-repo-graph-store-is-behind`. Every agent gating a branch then
meets a red full gate and has to work out from scratch that the red is not theirs. With nowhere to
WRITE that conclusion it is re-derived every time, and the real cost is not the retyping: it is that a
red gate stops meaning anything, which is how a fleet learns to read red as noise.

EVERY DECLARATION MUST NAME AN OWNING PLAN REF. A leg listed here is one nobody looks at again, which
is exactly what makes it dangerous — an unowned entry is how a real failure gets parked forever. The
ref points at the item that will remove it, so this list is a queue rather than a wastebasket.

The leg KEY is the stable id `bsc work gate` prints (`typecheck`, `vitest`, `graph-store`), not the
prose label, which gets reworded without anything being meant by it.",
    },
    CmdDoc {
        name: "seen",
        summary: "photograph the surface, read the pixels, and record the verdict on the change record",
        usage: "\
USAGE:
  bsc work seen [<ref>] [--window <label>] [--note <text>] [--dry-run] [--json|--pretty]

Captures the running app, runs the pixel census (`bsc shot analyze`), and appends the verdict to this
branch's change record.

WHY THIS EXISTS. MEASURED 2026-09-04: a spectrum-analyzer widget was built, passed a fully green
ten-leg gate, was reported as fixed, and rendered nothing. Nothing had broken -- `main` was 52 commits
behind `develop` and did not contain the file that binds the socket, so the binary on screen had the
window and none of the machinery. The gate was right and the report was wrong, and no surface in this
repo could have said so.

IT REFUSES BEFORE IT CAPTURES, and that refusal is the point rather than a safety rail. If this branch
is not in the app's branch, the running app CANNOT contain the work, and a green census taken from it
would be evidence for a claim nobody checked -- the same failure one level down. The refusal names the
command that fixes it.

--window IS WHY A WIDGET CAN BE LOOKED AT AT ALL. The app is not one window; a widget is a separate
webview labelled `bsc-widget-<id>`, and every capture path used to resolve `main` unconditionally. A
label that names no window is refused with the list that DO exist.

EVIDENCE, NOT ENFORCEMENT (maintainer, 2026-09-04). Nothing here blocks `verified`. A gate leg would
need the running app, and this repo already keeps the app out of the gate for exactly that reason: ten
worktree agents gating in parallel would each demand it and pin every node red. What changes is that a
verdict is REACHABLE, and that it lands where the reviewer reads it instead of in scrollback.

  <ref>             the plan ref. Defaults to the BRANCH, as `gate` does (1:1).
  --window <label>  which webview to photograph (default `main`)
  --note <text>     a line of your own, appended under the census
  --dry-run         capture and print the verdict, recording nothing",
    },
];

/// Everything the two verbs read off argv.
struct Args {
    json: bool,
    pretty: bool,
    full: bool,
    strict: bool,
    dry_run: bool,
    r#ref: Option<String>,
    note: Option<String>,
    /// `--test <name>`, REPEATABLE — the failures a known-red declaration accounts for. Empty leaves
    /// the declaration leg-level.
    tests: Vec<String>,
    db: Option<String>,
    /// `seen --window <label>` — WHICH webview to photograph. A widget is a separate window, and the
    /// tear-off surfaces are exactly the ones nothing else can look at.
    window: Option<String>,
    /// `seen --app-branch <name>` — the branch the running app is built from. Overridable only so the
    /// refusal is testable and so a differently-arranged checkout is not simply wrong.
    app_branch: Option<String>,
    positional: Vec<String>,
}

/// The branch the app's tree is checked out on. `main`, per the repo layout: the ROOT runs the app and
/// every branch integrates into `develop` elsewhere.
pub const DEFAULT_APP_BRANCH: &str = "main";

fn parse_args(raw: Vec<String>) -> Result<Args, String> {
    let a = Args {
        json: false,
        pretty: false,
        full: false,
        strict: false,
        dry_run: false,
        r#ref: None,
        note: None,
        tests: Vec::new(),
        db: None,
        window: None,
        app_branch: None,
        positional: Vec::new(),
    };
    let (mut a, positional) = bsc_cli_util::args::walk(raw, a, |flag, a: &mut Args, v| {
        match flag {
            "--json" => a.json = true,
            "--pretty" => a.pretty = true,
            "--full" => a.full = true,
            "--strict" => a.strict = true,
            "--dry-run" => a.dry_run = true,
            "--ref" => a.r#ref = Some(v.value("--ref needs a plan ref")?),
            "--note" => a.note = Some(v.value("--note needs text")?),
            // Repeatable: a leg may own more than one known failure, and replacing rather than
            // appending would silently drop the earlier ones.
            "--test" => a.tests.push(v.value("--test needs a test name")?),
            "--db" => a.db = Some(v.value("--db needs a path")?),
            "--window" => a.window = Some(v.value("--window needs a webview label, e.g. bsc-widget-spectrum")?),
            "--app-branch" => a.app_branch = Some(v.value("--app-branch needs a branch name")?),
            _ => return Ok(false),
        }
        Ok(true)
    })?;
    a.positional = positional;
    Ok(a)
}

pub fn run(raw: Vec<String>, prog: &str) -> Result<(), String> {
    let args = parse_args(raw)?;
    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &args.positional) {
        return Ok(());
    }
    match args.positional.first().map(String::as_str).unwrap_or("") {
        "gate" => cmd_gate(&args, prog),
        "known-red" => cmd_known_red(&args, prog),
        "seen" => cmd_seen(&args),
        other => Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, other)),
    }
}

// ── shared resolution ────────────────────────────────────────────────────────────────────────────

/// The repo this gate belongs to — the worktree we are standing in.
///
/// `--show-toplevel`, not the process cwd, so running from a subdirectory still finds the gate and the
/// artifact. A worktree has its own toplevel, which is the point: two worktrees gate independently.
fn repo_root() -> Result<PathBuf, String> {
    let out = std::process::Command::new("git")
        .args(["rev-parse", "--show-toplevel"])
        .output()
        .map_err(|e| format!("cannot run git: {e}"))?;
    if !out.status.success() {
        return Err("bsc work: not inside a git worktree, so there is no gate to run".into());
    }
    Ok(PathBuf::from(String::from_utf8_lossy(&out.stdout).trim()))
}

/// The plan ref this branch is working. See the `gate` help: the branch IS the ref (1:1).
///
/// A detached HEAD or a branch that is not a ref returns `None` rather than a guess. Recording gate
/// evidence against the wrong item is worse than recording none: the wrong change record then claims
/// a gate that was never run for it, which is precisely the untruth this verb exists to remove.
fn branch_ref(root: &Path) -> Option<String> {
    let out = std::process::Command::new("git")
        .current_dir(root)
        .args(["rev-parse", "--abbrev-ref", "HEAD"])
        .output()
        .ok()?;
    let b = String::from_utf8_lossy(&out.stdout).trim().to_string();
    (out.status.success() && !b.is_empty() && b != "HEAD").then_some(b)
}

fn open_store(db: Option<&str>) -> Result<plandb::Store, String> {
    let path = match db {
        Some(p) => PathBuf::from(p),
        None => std::env::var_os("BSC_PLAN_DB").map(PathBuf::from).ok_or(
            "bsc work: no plan store — set $BSC_PLAN_DB or pass --db <plan.db>",
        )?,
    };
    if !path.exists() {
        return Err(format!(
            "bsc work: no plan store at {} — `Store::open` would MINT an empty one, and a project \
             invented by a typo is worse than a refusal",
            path.display()
        ));
    }
    plandb::Store::open(&path).map_err(|e| format!("bsc work: cannot open {}: {e}", path.display()))
}

// ── gate ─────────────────────────────────────────────────────────────────────────────────────────

fn cmd_gate(args: &Args, prog: &str) -> Result<(), String> {
    let root = repo_root()?;

    // Resolve the ref BEFORE the gate runs. A two-minute build that then discovers it has nowhere to
    // record is the most expensive possible ordering, and the failure is knowable up front.
    let store = open_store(args.db.as_deref())?;
    let plan_ref = match args.r#ref.clone().or_else(|| branch_ref(&root)) {
        Some(r) => r,
        None => {
            return Err(format!(
                "{prog} gate: HEAD is detached, so there is no branch to read the ref from. \
                 Pass --ref <plan-ref>."
            ))
        }
    };
    if !args.dry_run && store.change_get(&plan_ref).map_err(|e| e.to_string())?.is_none() {
        // Refuse rather than create one. A change record is opened at the START of the work with the
        // title and reasoning that make it worth anything; one minted here would carry neither, and
        // would quietly satisfy the "every slice gets a change record" rule while being empty.
        return Err(format!(
            "{prog} gate: no change record for '{plan_ref}'. Open one first:\n  \
             bsc plan change new {plan_ref} --note \"<title>\" --description \"<what and why>\"\n  \
             (or pass --ref if this branch is not the item's ref, or --dry-run to just see the verdict)"
        ));
    }

    // REMOVE THE PREVIOUS VERDICT FIRST. The gate writes `target/gate-result.json` and this reads it
    // back — with no freshness check, so a run that DIES before writing one leaves the last run's
    // artifact on disk and it is read, printed and RECORDED as this run's result. Observed: a gate
    // killed partway through vitest reprinted the previous run's footer verbatim, `clippy FAIL` and
    // all, with timings identical to a tenth of a second — indistinguishable from a fresh verdict
    // unless you notice the numbers never moved.
    //
    // That is the evidence chain this verb exists to make trustworthy: `record` writes those legs onto
    // the change record, so a stale artifact does not merely mislead a reader, it files gate evidence
    // for a run that never finished. Deleting it first turns that into the ABSENT case, which the read
    // below already refuses — and an absent verdict reads as absent, never as a pass.
    let artifact = root.join("target").join("gate-result.json");
    let _ = std::fs::remove_file(&artifact);

    // Run the REAL gate, stdio inherited, so cargo's live progress and colours survive exactly as they
    // do when a person runs `npm run gate`. Wrapping it in a pipe to parse would leave the gate looking
    // frozen through every long compile — the same reason `gate.mjs` inherits stdio for each leg.
    let mut cmd = std::process::Command::new(if cfg!(windows) { "npm.cmd" } else { "npm" });
    cmd.current_dir(&root).arg("run").arg("gate");
    if args.full {
        cmd.arg("--").arg("--full");
    }
    let status = cmd.status().map_err(|e| {
        format!("{prog} gate: cannot run npm: {e} — the gate is an npm script and needs the build tier")
    })?;

    let text = std::fs::read_to_string(&artifact).map_err(|e| {
        format!(
            "{prog} gate: the gate exited {} but wrote no verdict at {} ({e}).\n  \
             Nothing was recorded — an absent verdict reads as ABSENT, never as a pass.",
            status.code().unwrap_or(-1),
            artifact.display()
        )
    })?;
    let result: GateResult = serde_json::from_str(&text)
        .map_err(|e| format!("{prog} gate: {} is not a gate verdict: {e}", artifact.display()))?;

    let known = store.known_red_list().map_err(|e| e.to_string())?;
    let verdicts = classify(&result, &known);
    let (red, known_red, unexplained) = tally(&verdicts);

    if !args.dry_run {
        record(&store, &plan_ref, &result.mode, &verdicts).map_err(|e| format!("{prog} gate: {e}"))?;
    }

    emit(args, &plan_ref, &result, &verdicts, (red, known_red, unexplained));

    // The exit code follows UNEXPLAINED failures, not red ones — see the help. `--strict` restores
    // "any red fails", for a caller that does not want a declaration to speak for it.
    let failing = if args.strict { red } else { unexplained };
    if failing > 0 {
        return Err(format!(
            "{prog} gate: {failing} {} — recorded on '{plan_ref}'",
            if args.strict { "red leg(s)" } else { "UNEXPLAINED red leg(s)" }
        ));
    }
    Ok(())
}

/// Write the verdict onto the change record — every leg, plus the gate MODE.
///
/// The mode rides along as its own leg because a green SCOPED gate and a green FULL one are different
/// claims, and this repo's recurring failure is a gate that passes while covering less than the reader
/// assumes. Without it the record cannot tell the two apart, and "the gate was green" would mean
/// whichever the reader guessed.
///
/// Separated from [`cmd_gate`] so the recording is testable against a temp store without running a
/// two-minute build.
fn record(store: &plandb::Store, plan_ref: &str, mode: &str, verdicts: &[Verdict]) -> Result<(), String> {
    for v in verdicts {
        store
            .change_set_gate(plan_ref, &v.key, v.recorded_result())
            .map_err(|e| format!("could not record '{}': {e}", v.key))?;
    }
    store
        .change_set_gate(plan_ref, "gate-mode", mode)
        .map_err(|e| format!("could not record the gate mode: {e}"))?;
    Ok(())
}

fn emit(args: &Args, plan_ref: &str, result: &GateResult, verdicts: &[Verdict], t: (usize, usize, usize)) {
    let (red, known_red, unexplained) = t;
    let payload = serde_json::json!({
        "ref": plan_ref,
        "mode": result.mode,
        "reason": result.reason,
        "recorded": !args.dry_run,
        "red": red,
        "knownRed": known_red,
        "unexplained": unexplained,
        "legs": verdicts.iter().map(|v| serde_json::json!({
            "key": v.key,
            "label": v.label,
            "result": v.recorded_result(),
            "seconds": v.seconds,
            "knownRedOwner": v.known_red_owner,
        })).collect::<Vec<_>>(),
    });
    bsc_cli_util::emit(args.pretty, args.json, &payload, || {
        let mut out = String::new();
        out.push_str(&format!("\ngate: {} — {}\n", result.mode.to_uppercase(), result.reason));
        for v in verdicts {
            let owner = match &v.known_red_owner {
                Some(r) => format!("  (known-red, owned by {r})"),
                None => String::new(),
            };
            out.push_str(&format!(
                "  {:<20} {:<5} {:>6.1}s{}\n",
                v.key,
                v.recorded_result().to_uppercase(),
                v.seconds,
                owner
            ));
        }
        // ALWAYS state the split. The exit code does not follow the red count, and a reader who
        // assumed it did would read a zero exit as "nothing was red".
        out.push_str(&format!(
            "\n  {red} red, {known_red} known-red → {unexplained} unexplained\n"
        ));
        out.push_str(&if args.dry_run {
            format!("  --dry-run: nothing recorded on '{plan_ref}'\n")
        } else {
            format!("  recorded {} leg(s) + the gate mode on '{plan_ref}'\n", verdicts.len())
        });
        out
    });
}

// ── known-red ────────────────────────────────────────────────────────────────────────────────────

fn cmd_known_red(args: &Args, prog: &str) -> Result<(), String> {
    let store = open_store(args.db.as_deref())?;
    match args.positional.get(1).map(String::as_str).unwrap_or("list") {
        "list" => {
            let all = store.known_red_list().map_err(|e| e.to_string())?;
            bsc_cli_util::emit(args.pretty, args.json, &all, || {
                if all.is_empty() {
                    return "(no gate leg is declared known-red)\n".to_string();
                }
                all.iter()
                    .map(|(leg, v)| {
                        let owner = v.get("ref").and_then(|x| x.as_str()).unwrap_or("(unowned)");
                        let note = v.get("note").and_then(|x| x.as_str()).unwrap_or("");
                        format!("{leg:<14} {owner}{}", if note.is_empty() { String::new() } else { format!("  — {note}") })
                    })
                    .collect::<Vec<_>>()
                    .join("\n")
                    + "\n"
            });
            Ok(())
        }
        "add" => {
            let leg = args
                .positional
                .get(2)
                .ok_or_else(|| {
                    format!("usage: {prog} known-red add <leg-key> --ref <plan-ref> [--test <name>]… [--note <text>]")
                })?;
            let owner = args.r#ref.as_deref().unwrap_or("");
            // `--test` NARROWS the declaration to the failures it names. Without it the declaration is
            // leg-level and excuses everything in that leg, which is how a freshly broken test rode
            // out behind `0 unexplained`. Not required, because `tsc` and `eslint` genuinely cannot
            // enumerate — but a leg that CAN name its failures should.
            store.known_red_add(leg, owner, args.note.as_deref(), &args.tests)?;
            if !args.json {
                let scope = if args.tests.is_empty() {
                    " (LEG-LEVEL — excuses every failure in this leg; pass --test to narrow it)".to_string()
                } else {
                    format!(" for {}", args.tests.join(", "))
                };
                println!("known-red: {leg} → owned by {owner}{scope}");
            }
            Ok(())
        }
        "remove" => {
            let leg = args
                .positional
                .get(2)
                .ok_or_else(|| format!("usage: {prog} known-red remove <leg-key>"))?;
            let had = store.known_red_remove(leg)?;
            if !args.json {
                // Reporting "removed" for something that was never declared is an act that did not
                // happen — say which it was.
                println!(
                    "{}",
                    if had { format!("known-red: {leg} removed") } else { format!("known-red: {leg} was not declared") }
                );
            }
            Ok(())
        }
        other => Err(format!("unknown known-red command '{other}'\n\n{}", bsc_cli_util::surface::help_for(prog, TAGLINE, COMMANDS, "known-red"))),
    }
}


// ── seen: a UI slice is not done until someone looked at it ──────────────────────────────────────

/// Whether the RUNNING app can possibly contain this branch's code.
///
/// MEASURED, 2026-09-04, and this whole verb exists because of it: a widget slice passed a fully green
/// ten-leg gate, was reported as fixed, and rendered nothing — because `main` was 52 commits behind
/// `develop` and did not contain the file that binds the socket. Nothing was broken. The gate was
/// right and the report was wrong.
///
/// So the question a pixel verdict has to answer FIRST is not "did it render" but "is the code I am
/// judging even in the binary on screen". `Unreachable` is the exact case above and is a REFUSAL: a
/// green census taken from a stale binary is worse than no census, because it is evidence for a claim
/// nobody checked.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Reach {
    /// The branch tip is an ancestor of the app's branch, and the binary is not behind it.
    Live,
    /// In the app's branch, but the binary predates it — a rebuild away, not a promote.
    BinaryStale { reason: String },
    /// Not in the app's branch at all. The app CANNOT contain this work.
    Unreachable { app_branch: String, commits_ahead: u64 },
}

/// The pure rule, so the refusal is testable without a repo, a binary or a running app.
///
/// `in_app_branch` is the hard fact — `git merge-base --is-ancestor <head> <app branch>` — and it
/// outranks everything: an mtime cannot rescue code that is not in the tree the app was built from.
pub fn judge_reach(
    in_app_branch: bool,
    app_branch: &str,
    commits_ahead: u64,
    binary_stale: Option<&str>,
) -> Reach {
    if !in_app_branch {
        return Reach::Unreachable { app_branch: app_branch.to_string(), commits_ahead };
    }
    match binary_stale {
        Some(reason) => Reach::BinaryStale { reason: reason.to_string() },
        None => Reach::Live,
    }
}

impl Reach {
    /// The refusal text, or `None` when a capture is worth taking.
    ///
    /// It names the COMMAND that fixes it. A refusal that leaves the reader to work out what to run
    /// is a refusal they route around.
    pub fn refusal(&self) -> Option<String> {
        match self {
            Reach::Live => None,
            Reach::BinaryStale { reason } => Some(format!(
                "the app binary is stale ({reason}), so a capture would photograph older code.\n  \
                 Restart the app (`npm run app:dev`) and retry — this is a rebuild, not a promote."
            )),
            Reach::Unreachable { app_branch, commits_ahead } => Some(format!(
                "this branch is NOT in `{app_branch}`, which is what the app runs — {commits_ahead} \
                 commit(s) ahead of it. The running app CANNOT contain this work, so a pixel verdict \
                 would be evidence about code that is not on screen.\n  \
                 Land it and run `npm run promote`, then retry."
            )),
        }
    }
}

/// Is `head` an ancestor of `app_branch`?
fn in_branch(root: &Path, head: &str, app_branch: &str) -> bool {
    std::process::Command::new("git")
        .current_dir(root)
        .args(["merge-base", "--is-ancestor", head, app_branch])
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

/// How many commits `head` has that `app_branch` does not.
fn commits_ahead_of(root: &Path, head: &str, app_branch: &str) -> u64 {
    std::process::Command::new("git")
        .current_dir(root)
        .args(["rev-list", "--count", &format!("{app_branch}..{head}")])
        .output()
        .ok()
        .and_then(|o| String::from_utf8_lossy(&o.stdout).trim().parse().ok())
        .unwrap_or(0)
}

/// `bsc work seen [<ref>]` — photograph the surface, read the pixels, and record the verdict.
///
/// EVIDENCE, NOT ENFORCEMENT (maintainer, 2026-09-04). Nothing here blocks `verified`; a gate leg
/// would need the running app, and this repo already refuses to wire the app into the gate because ten
/// worktree agents gating in parallel would each demand it and pin every node red. What changes is
/// that a UI slice can produce a pixel verdict AT ALL — a widget is a separate webview, and until
/// `--window` existed no capture could reach one — and that the verdict lands where the reviewer reads
/// it rather than in a session's scrollback.
fn cmd_seen(args: &Args) -> Result<(), String> {
    let root = repo_root()?;
    let plan_ref = match args.positional.get(1) {
        Some(r) => r.clone(),
        None => branch_ref(&root).ok_or(
            "bsc work seen: detached HEAD — name the ref, or check out the branch whose item this is",
        )?,
    };
    let app_branch = args.app_branch.as_deref().unwrap_or(DEFAULT_APP_BRANCH);
    let window = args.window.as_deref().unwrap_or("main");

    let reach = judge_reach(
        in_branch(&root, "HEAD", app_branch),
        app_branch,
        commits_ahead_of(&root, "HEAD", app_branch),
        None,
    );
    if let Some(why) = reach.refusal() {
        return Err(format!("bsc work seen: {why}"));
    }

    // Through the SAME binary, so the census a session records is the one `bsc shot analyze` prints —
    // two implementations of "did anything render" would eventually disagree, and the disagreement
    // would surface as a recorded verdict nobody could reproduce.
    let exe = std::env::current_exe().map_err(|e| format!("cannot locate this binary: {e}"))?;
    let out = std::process::Command::new(&exe)
        .args(["shot", "analyze", "--window", window, "--json"])
        .output()
        .map_err(|e| format!("cannot run `bsc shot analyze`: {e}"))?;
    let stdout = String::from_utf8_lossy(&out.stdout).to_string();
    if !out.status.success() {
        let stderr = String::from_utf8_lossy(&out.stderr);
        return Err(format!(
            "bsc work seen: the capture failed — {}\n  Is the app running, and is `{window}` open?",
            stderr.trim().lines().next().unwrap_or("no detail")
        ));
    }
    let census: serde_json::Value = serde_json::from_str(stdout.trim())
        .map_err(|e| format!("bsc work seen: the census was not JSON ({e}): {stdout}"))?;

    let note = format!(
        "SEEN: {window} — {}{}",
        serde_json::to_string(&census).unwrap_or_else(|_| stdout.trim().to_string()),
        args.note.as_deref().map(|n| format!("\n{n}")).unwrap_or_default()
    );
    if !args.dry_run {
        let store = open_store(args.db.as_deref())?;
        store
            .change_add_note(&plan_ref, "claude", &note)
            .map_err(|e| format!("bsc work seen: could not record the verdict: {e}"))?;
    }

    let payload = serde_json::json!({
        "ref": plan_ref,
        "window": window,
        "appBranch": app_branch,
        "recorded": !args.dry_run,
        "census": census,
    });
    bsc_cli_util::emit(args.pretty, args.json, &payload, || {
        format!("seen: {window}\n  {}\n  recorded on {plan_ref}\n", stdout.trim())
    });
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::gate::{classify, Leg};
    use serde_json::json;


    /// THE PREVIOUS VERDICT IS DELETED BEFORE THE GATE RUNS, and nothing at run time can observe that
    /// — so this reads the materialized source, the same way `bsc-graph`'s store-lock guard does.
    ///
    /// The hole: `gate` runs `npm run gate`, then reads `target/gate-result.json` with no freshness
    /// check. A run that DIES before writing one leaves the previous run's artifact on disk, and it is
    /// read, printed and RECORDED as this run's result. Observed on 2026-09-08 — a gate killed partway
    /// through vitest reprinted the earlier run's `clippy FAIL` footer with timings identical to a
    /// tenth of a second. `record` writes those legs onto the change record, so the cost is not a
    /// misleading line, it is gate EVIDENCE filed for a run that never finished.
    ///
    /// Asserting the ORDER, not the presence: a removal that happened after the run would restore the
    /// bug exactly while still containing both statements.
    #[test]
    fn the_previous_verdict_is_removed_before_the_gate_runs() {
        let src = std::fs::read_to_string(
            std::path::Path::new(env!("OUT_DIR")).join("crate.rs"),
        )
        .expect("the materialized crate source");
        // `fn cmd_gate(`, not `fn gate(` — there is a `gate` MODULE too, and matching it instead made
        // this scan pass against the very bug it exists to catch. A scanner that stopped matching
        // reports nothing and reads as a pass, so the span is asserted below before anything is
        // concluded from it.
        let start = src.find("fn cmd_gate(").expect("cmd_gate is in the materialized source");
        let rest = &src[start + 1..];
        let end = rest.find("\nfn ").map(|e| start + 1 + e).unwrap_or(src.len());
        let body = &src[start..end];
        assert!(
            body.len() > 500 && body.len() < 20_000,
            "the cmd_gate span is {} bytes — the scan is mis-parsing, not the code being small",
            body.len()
        );

        let remove = body
            .find("remove_file(&artifact)")
            .expect("gate must DELETE the previous verdict — a stale one is reported as fresh");
        let run = body.find("cmd.status()").expect("gate must run the gate");
        assert!(
            remove < run,
            "the removal must come BEFORE the run; after it, a died run still reports the last verdict"
        );
        // …and the read must come after the run, or it could only ever see the file we just deleted.
        let read = body.find("read_to_string(&artifact)").expect("gate must read the verdict back");
        assert!(run < read, "the verdict is read after the run");
    }

    #[test]
    fn work_not_in_the_apps_branch_is_refused_before_any_capture() {
        // THE MEASURED FAILURE, as a rule. A widget slice passed a green
        // ten-leg gate and rendered nothing because `main` was 52 commits
        // behind `develop` and did not contain the file that binds the socket.
        // A pixel census taken then would have photographed the OLD binary and
        // been recorded as evidence.
        let r = judge_reach(false, "main", 52, None);
        assert_eq!(r, Reach::Unreachable { app_branch: "main".into(), commits_ahead: 52 });
        let why = r.refusal().expect("this must refuse");
        assert!(why.contains("52 commit"), "the refusal hides the distance: {why}");
        assert!(why.contains("main"), "{why}");
        assert!(why.contains("promote"), "the refusal must name the command that fixes it: {why}");
    }

    #[test]
    fn a_stale_binary_is_a_rebuild_and_says_so_rather_than_sending_you_to_promote() {
        // Different problem, different fix. Telling someone to promote when the
        // code is already on `main` sends them at a no-op and leaves the stale
        // binary in place.
        let r = judge_reach(true, "main", 0, Some("3-commits-behind-main"));
        let why = r.refusal().expect("this must refuse");
        assert!(why.contains("rebuild, not a promote"), "{why}");
        assert!(why.contains("3-commits-behind-main"), "the reason is dropped: {why}");
    }

    #[test]
    fn code_the_app_actually_has_is_allowed_through() {
        let r = judge_reach(true, "main", 0, None);
        assert_eq!(r, Reach::Live);
        assert!(r.refusal().is_none(), "a live branch must not be refused");
    }

    #[test]
    fn being_in_the_branch_never_rescues_being_behind_it_and_vice_versa() {
        // Ordering matters: the ancestry fact OUTRANKS the mtime one. Work that
        // is not in the tree the app was built from cannot be rescued by a
        // fresh binary, so `Unreachable` must win even when the binary is
        // perfectly current.
        assert!(matches!(judge_reach(false, "main", 1, None), Reach::Unreachable { .. }));
        assert!(matches!(judge_reach(false, "main", 1, Some("x")), Reach::Unreachable { .. }));
    }

    #[test]
    fn the_app_branch_is_main_because_the_root_runs_the_app() {
        // Named rather than inlined: `develop` is where work integrates and
        // `main` is what the user is looking at, and judging against the wrong
        // one would make every refusal either constant or absent.
        assert_eq!(DEFAULT_APP_BRANCH, "main");
    }

    #[test]
    fn seen_is_documented_so_a_verb_cannot_be_added_silently() {
        let doc = COMMANDS.iter().find(|c| c.name == "seen").expect("the verb is in the catalog");
        assert!(doc.usage.contains("--window"), "seen does not document --window");
        assert!(doc.usage.contains("EVIDENCE, NOT ENFORCEMENT"), "the stated policy is missing");
    }
    fn store(tag: &str) -> (plandb::Store, PathBuf) {
        let dir = std::env::temp_dir().join(format!("bsc-work-{}-{tag}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let p = dir.join("proj.db");
        let _ = std::fs::remove_file(&p);
        (plandb::Store::open(&p).unwrap(), p)
    }

    /// The minimum change record, so the recording tests have somewhere to write.
    fn new_change(s: &plandb::Store, r: &str) {
        s.change_upsert(&plandb::changes::Change {
            r#ref: r.into(),
            title: "t".into(),
            body: "b".into(),
            ..Default::default()
        })
        .unwrap();
    }

    fn result(mode: &str, legs: &[(&str, bool)]) -> GateResult {
        GateResult {
            version: 1,
            mode: mode.into(),
            reason: "test".into(),
            passed: legs.iter().all(|(_, ok)| *ok),
            legs: legs
                .iter()
                .map(|(k, ok)| Leg { key: (*k).into(), label: (*k).into(), ok: *ok, seconds: 1.0, failures: Vec::new() })
                .collect(),
        }
    }

    #[test]
    fn every_leg_and_the_gate_mode_land_on_the_change_record() {
        let (s, _p) = store("record");
        new_change(&s, "api-slice");
        let v = classify(&result("full", &[("typecheck", true), ("vitest", false)]), &Default::default());
        record(&s, "api-slice", "full", &v).unwrap();

        let c = s.change_get("api-slice").unwrap().expect("the change exists");
        assert_eq!(c.gates["typecheck"], "pass");
        assert_eq!(c.gates["vitest"], "fail");
        // The MODE is evidence too: a green scoped gate and a green full one are different claims.
        assert_eq!(c.gates["gate-mode"], "full");
    }

    #[test]
    fn a_known_red_leg_is_still_written_as_a_failure() {
        // The invariant restated at the STORE boundary, not only in the pure classifier: whatever the
        // run's exit code does, what lands durably must be what happened.
        let (s, _p) = store("knownred");
        new_change(&s, "api-slice");
        let mut declared = serde_json::Map::new();
        declared.insert("graph-promote-check".into(), json!({ "ref": "owning-item" }));
        let v = classify(&result("full", &[("graph-promote-check", false)]), &declared);
        record(&s, "api-slice", "full", &v).unwrap();

        let c = s.change_get("api-slice").unwrap().unwrap();
        assert_eq!(c.gates["graph-promote-check"], "fail", "a declaration explains, it never launders");
    }

    #[test]
    fn recording_a_second_run_supersedes_the_first_rather_than_appending() {
        // Gate evidence is the LATEST observation, unlike notes, which are append-only. A record that
        // kept "vitest: fail" beside "vitest: pass" could not answer whether the gate is green now.
        let (s, _p) = store("supersede");
        new_change(&s, "api-slice");
        record(&s, "api-slice", "scoped", &classify(&result("scoped", &[("vitest", false)]), &Default::default())).unwrap();
        record(&s, "api-slice", "full", &classify(&result("full", &[("vitest", true)]), &Default::default())).unwrap();
        let c = s.change_get("api-slice").unwrap().unwrap();
        assert_eq!(c.gates["vitest"], "pass");
        assert_eq!(c.gates["gate-mode"], "full");
    }

    #[test]
    fn a_plan_store_that_does_not_exist_is_refused_rather_than_minted() {
        // `Store::open` would happily create one, and a project invented by a typo would then accept
        // gate evidence for a change record nobody can find again.
        let missing = std::env::temp_dir().join(format!("bsc-work-absent-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&missing);
        let err = match open_store(Some(&missing.to_string_lossy())) {
            Ok(_) => panic!("a missing store must be refused, not minted"),
            Err(e) => e,
        };
        assert!(err.contains("MINT"), "the refusal says why: {err}");
        assert!(!missing.exists(), "the probe must not create it");
    }

    #[test]
    fn the_flags_parse_and_an_unknown_one_is_refused() {
        let a = parse_args(vec!["gate".into(), "--full".into(), "--ref".into(), "r1".into(), "--strict".into()]).unwrap();
        assert!(a.full && a.strict);
        assert_eq!(a.r#ref.as_deref(), Some("r1"));
        assert_eq!(a.positional, vec!["gate"]);
        // A silently ignored flag is how a caller believes it asked for something it did not.
        assert!(parse_args(vec!["gate".into(), "--fulll".into()]).is_err());
        // A flag that needs a value and has none must not swallow the next token as one.
        assert!(parse_args(vec!["gate".into(), "--ref".into()]).is_err());
    }
}

